pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(100, "Test", "TST"); }
    function testRegression_property() public {
        uint256 initialSupply = c.totalSupply();
        c.burn(50);
        uint256 finalSupply = c.totalSupply();
        assertTrue(finalSupply == initialSupply - 50);
    }
}
